"""Five fresh retrospective suites. Expectations precede execution; no rule-ID assertions."""
from pathlib import Path
import json
cases=[]
urls={
 '00374':'https://healthservice.hse.ie/documents/6729/374_Trabectedin_monotherapy.pdf',
 '00228':'https://healthservice.hse.ie/documents/6564/228_eriBULin.pdf',
 '00205':'https://healthservice.hse.ie/documents/6546/205_V8_Peg_Lipo_DOXO_28_day.pdf',
 '00462':'https://healthservice.hse.ie/documents/6735/462_v4_PegylatedLiposomalDOX_20mgm2_21_days.pdf',
 '00554':'https://healthservice.hse.ie/documents/6742/554_vinblastine_MTX_SAMV.pdf'}
def add(code,title,inputs,kind,rationale,lines,**checks):
 cases.append({'case_id':f'{code}-{1+sum(x["code"]==code for x in cases):02}','code':code,'title':title,'inputs':inputs,'expected':{'kind':kind,**checks},'source':{'url':urls[code],'retained_lines':lines,'rationale':rationale}})

# Trabectedin: separate supportive-care prerequisites and interval history from current clearance.
for phase in ['baseline','on_treatment','restart']:
 add('00374',f'Unconfirmed mandatory dexamethasone with reassuring retreatment criteria, {phase}',dict(assessment_phase=phase,dex_premed_confirmed=False,all_retreatment_criteria_met=True,anc=2,platelets=160,hepatic_impairment_band='moderate',actual_dose_mg_m2=1.2),'hold','The corticosteroid prerequisite is independent of blood-count recovery and the hepatic dose-review pathway.','L178–L181; L149–L156',match='dexamethasone|corticosteroid|premed')
 add('00374',f'Yellow-fever vaccination despite favourable treatment context, {phase}',dict(assessment_phase=phase,yellow_fever_vaccination=True,eligible_sts_context_confirmed=True,ecog=0,anc=2,platelets=160,dex_premed_confirmed=True),'contra','Yellow-fever vaccination is explicitly contraindicated; tumour eligibility and premedication do not remove that restriction.','L192–L194')
 add('00374',f'Current severe nonhaematological event versus normal prior-cycle history, {phase}',dict(assessment_phase=phase,current_other_toxicity_grade=3,prior_cycle_other_toxicity_grade=0,all_retreatment_criteria_met=True,anc=2,platelets=160,actual_dose_mg_m2=1.2),'hold','A currently severe adverse event cannot be cleared by a normal previous-cycle score or composite retreatment tick.','L95–L100; L111–L128')
 add('00374',f'Short prior neutropenia complicated by infection after count recovery, {phase}',dict(assessment_phase=phase,prior_cycle_anc_nadir=.4,prior_neutropenia_days=1,prior_neutropenia_fever_infection=True,anc=2,platelets=160,actual_dose_mg_m2=1.2,hepatic_impairment_band='moderate'),'review','Fever/infection qualifies the prior ANC<0.5 event even when duration does not exceed five days. Current recovery and hepatic percentages do not erase history or supply a numeric combined dose.','L113–L122; L149–L156',match='neutropen|ANC')
for dose in [1.5,1.2]:
 add('00374',f'Recovered platelets after prior nadir24 at prescribed dose{dose}',dict(assessment_phase='restart',prior_cycle_platelet_nadir=24,platelets=180,anc=2,actual_dose_mg_m2=dose,all_retreatment_criteria_met=True,dex_premed_confirmed=True),'review','Prior platelet nadir below25 remains a next-cycle reduction event despite fully recovered current counts; the actual prescription must be reviewed.','L99–L100; L123; L142–L145',match='platelet')
for field in ['prior_cycle_alt_peak','prior_cycle_ast_peak']:
 add('00374',f'Recovered transaminases after prior high {field} with moderate hepatic band',dict(assessment_phase='restart',**{field:3.2},transaminases_recovered_by_day21=True,alt_uln_multiple=1,ast_uln_multiple=1,bilirubin_uln_multiple=1,hepatic_impairment_band='moderate',actual_dose_mg_m2=1.2),'review','NCCP prior-cycle transaminase criteria and organ-impairment percentages require reconciliation; present normal values cannot erase the historic event. The retained NCCP/SmPC timing disagreement stays review-only.','L124–L128; L149–L156',match='transamin|ALT|AST')
add('00374','Unconfirmed STS line eligibility despite recovered prior toxicity',dict(assessment_phase='restart',eligible_sts_context_confirmed=False,current_other_toxicity_grade=0,prior_cycle_other_toxicity_grade=3,actual_dose_mg_m2=1.2,dex_premed_confirmed=True),'review','Recovery establishes neither tumour setting nor anthracycline/ifosfamide failure or unsuitability.','L19–L22',match='sarcoma|anthracycline|ifosfamide|indicat')
for missing in ['ck_uln_multiple','albumin_g_l','haemoglobin_g_dl']:
 values=dict(assessment_phase='restart',all_retreatment_criteria_met=True,anc=2,platelets=160,haemoglobin_g_dl=11,albumin_g_l=35,bilirubin_uln_multiple=1,alt_uln_multiple=1,ast_uln_multiple=1,alp_uln_multiple=1,crcl_ml_min=80,ck_uln_multiple=1,dex_premed_confirmed=True);del values[missing]
 add('00374',f'Composite retreatment tick with missing required laboratory domain {missing}',values,'partial','A composite confirmation must not claim complete assessment of an omitted required current laboratory criterion.','L38–L57',missing_input=missing)

# Eribulin: preserve shared-context identity while challenging current/history disagreement.
for indication in ['00228a','00228b']:
 context=dict(indication_id=indication,liposarcoma_eligibility_confirmed=True,dose_basis='base')
 for day in [1,8]:
  add('00228',f'Current severe mucositis overrides restart confirmations, {indication}/Day{day}',dict(**context,assessment_phase='treatment_day',assessment_day=day,mucositis_grade=3,other_nonhaem_toxicity_grade=0,neuropathy_grade=0,restart_requested=True,current_delay_criteria_resolved=True,consultant_restart_plan_confirmed=True,anc_x10e9_l=2,platelets_x10e9_l=180,current_eribulin_dose_level='0.97'),'hold','Current grade3 nonhaematological toxicity delays either scheduled dose despite a contradictory recovery tick.','L89–L95')
 add('00228',f'Numeric prolonged nadir survives false legacy flag, {indication}',dict(**context,assessment_phase='treatment_day',assessment_day=1,prior_anc_nadir_x10e9_l=.4,days_prior_anc_below_05=8,prior_neutropenic_fever_or_infection=False,prolonged_anc_below_0_5_over_7d=False,current_eribulin_dose_level='0.62',anc_x10e9_l=2,platelets_x10e9_l=180,child_pugh='A'),'review','Direct interval history meeting ANC<0.5 for>7days must be reconciled even when a legacy composite flag is false; the reduced prescription and organ advice cannot generate a numeric dose.','L110–L122; L127–L133',match='neutropen|ANC|nadir')
 add('00228',f'Numeric low-platelet bleeding history survives false composite flag, {indication}',dict(**context,assessment_phase='treatment_day',assessment_day=8,prior_platelet_nadir_x10e9_l=45,prior_platelet_bleeding_or_transfusion=True,platelets_below_50_with_bleeding_or_transfusion=False,current_eribulin_dose_level='0.97',anc_x10e9_l=2,platelets_x10e9_l=180,child_pugh='B'),'review','A historical platelet count<50 with bleeding/transfusion remains dose-modification history despite current recovery and a contradictory boolean.','L114–L122',match='platelet|haemorr|bleed')
 add('00228',f'Current low ANC with infection despite false acute-FN flag, {indication}',dict(**context,assessment_phase='treatment_day',assessment_day=8,anc_x10e9_l=.8,platelets_x10e9_l=180,active_infection=True,acute_febrile_neutropenia=False,current_eribulin_dose_level='0.62',restart_requested=True,current_delay_criteria_resolved=True,consultant_restart_plan_confirmed=True),'hold','The actual current ANC delay is independent of a negative composite acute-FN field and of a previously reduced dose.','L91–L95')
 add('00228',f'Child-Pugh C despite normal entered LFTs and reduced prescription, {indication}',dict(**context,assessment_phase='treatment_day',assessment_day=1,child_pugh='C',alt_uln_multiple=1,ast_uln_multiple=1,bilirubin_uln_multiple=1,current_eribulin_dose_level='0.62',anc_x10e9_l=2,platelets_x10e9_l=180),'hold','A normal laboratory sample does not remove a documented severe cirrhotic hepatic category; source says not recommended rather than a formal absolute contraindication.','L127–L133',forbid_action=['contraindicated'])
 add('00228',f'Combined organ advice with an already reduced current prescription, {indication}',dict(**context,assessment_phase='treatment_day',assessment_day=8,creatinine_clearance_ml_min=40,eribulin_renal_band='lt50',child_pugh='B',current_eribulin_dose_level='0.62',planned_eribulin_base_dose_mg_m2=.62,anc_x10e9_l=2,platelets_x10e9_l=180),'review','Renal80% and hepatic50% are original-dose guidance; they cannot be compounded with a prior reduction or used to invent a new prescription.','L123–L133',match='renal|hepatic|Child')
 add('00228',f'Congenital long QT dominates recovered prior adverse event, {indication}',dict(**context,assessment_phase='treatment_day',congenital_long_qt=True,previous_grade_3_4_nonhaem=True,other_nonhaem_toxicity_grade=0,current_eribulin_dose_level='0.97',anc_x10e9_l=2,platelets_x10e9_l=180),'contra','Congenital longQT is an exclusion independent of toxicity recovery and blood-count eligibility.','L70–L74')
 add('00228',f'Initial platelet100 is not the treatment-day75 threshold, {indication}',dict(**context,assessment_phase='initial_eligibility',assessment_day=1,anc_x10e9_l=1.6,platelets_x10e9_l=100,child_pugh='A',current_eribulin_dose_level='0.97'),'hold','Initial eligibility requires platelets>100; dose-reduced organ advice cannot substitute the separate treatment-day platelet threshold.','L54–L57; L91–L95')
 add('00228',f'Trastuzumab partner context with mild mucositis, {indication}',dict(**context,assessment_phase='treatment_day',assessment_day=8,additional_trastuzumab=True,mucositis_grade=1,anc_x10e9_l=2,platelets_x10e9_l=180,current_eribulin_dose_level='1.23'),'review' if indication=='00228b' else 'observe','The optional trastuzumab footnote belongs to breast cancer, not liposarcoma; mild mucositis does not establish or alter that context.','L21–L30; L42',**({'match':'trastuzumab'} if indication=='00228b' else {'absent':'trastuzumab.*(not supported|not.*liposarcoma|outside|restricted)'}))

# PLD50: protected breast and sarcoma each get the same cross-toxicity safety challenges.
for ctx in ['breast','sarcoma']:
 base=dict(indication_context=ctx,assessment_stage='ongoing',correct_pegylated_formulation=True)
 add('00205',f'Grade1PPE after previous severe toxicity at one-week review plus hepatic advice, {ctx}',dict(**base,ppe_grade=1,stomatitis_grade=0,prior_grade3_4_skin_or_stomatitis=True,toxicity_delay_weeks=1,bilirubin_umol_l=50,current_pld_mg_m2=37.5),'hold','The second weekly delay after previous severe skin/mouth toxicity persists despite mild current grade and a separate hepatic percentage.','L138–L153; L124–L127')
 add('00205',f'Grade2stomatitis with resolved PPE at one-week review, {ctx}',dict(**base,ppe_grade=0,stomatitis_grade=2,toxicity_delay_weeks=1,current_pld_mg_m2=50,anc_x10e9_l=1.6,platelets_x10e9_l=180),'hold','Skin recovery does not clear current grade2 mouth toxicity; source requires another week of delay.','L154–L159')
 add('00205',f'Current severe neutropenia with hepatic reduction advice, {ctx}',dict(**base,anc_x10e9_l=.4,platelets_x10e9_l=180,bilirubin_umol_l=50,current_pld_mg_m2=37.5,previous_severe_cytopenia=False),'hold','A source choice of future severe-count reduction versus growth-factor support cannot permit dosing through current ANC<0.5; hepatic advice cannot override it.','L103–L107; L124–L127')
 add('00205',f'Current grade3mucositis at two-week review despite dialysis no-adjustment advice, {ctx}',dict(**base,mucositis_grade=3,toxicity_delay_weeks=2,haemodialysis=True,crcl_ml_min=80,current_pld_mg_m2=37.5),'stop','At the two-week review the source current grade3 mouth-toxicity row says discontinue; renal no-adjustment advice is not clearance.','L160–L161; L128–L129')
 add('00205',f'Pre-existing cardiomyopathy with normal current EF and low exposure, {ctx}',dict(**base,preexisting_cardiomyopathy_or_chf=True,lvef_percent=65,symptomatic_cardiac_dysfunction=False,cumulative_anthracycline_mg_m2=100,current_pld_mg_m2=50),'review','Pre-existing cardiac disease remains a caution despite a normal current EF and exposure below450; it is not an NCCP absolute exclusion.','L73–L77; L194–L199',match='cardiac|cardiomyopathy|heart',forbid_action=['contraindicated'])
 add('00205',f'Current infusion reaction without prior history or high selected grade, {ctx}',dict(**base,current_infusion_reaction=True,prior_infusion_reaction=False,infusion_reaction_grade=0,anc_x10e9_l=1.6,platelets_x10e9_l=180,current_pld_mg_m2=50),'hold','A reaction occurring now requires intervention/reassessment; a default grade0 and absent previous history cannot clear current symptoms.','L48–L51; L200–L204',match='infusion|reaction')
 add('00205',f'Actual hypersensitivity versus historical infusion-management plan, {ctx}',dict(**base,hypersensitivity=True,prior_infusion_reaction=True,current_infusion_reaction=False,infusion_reaction_grade=0,current_pld_mg_m2=37.5),'contra','Actual hypersensitivity is a source exclusion; the historical slower-infusion plan is not permission to administer.','L73–L75; L200–L204')
 add('00205',f'Hepatic original-dose advice with reduced current PLD, {ctx}',dict(**base,current_pld_mg_m2=37.5,original_pld_mg_m2=50,bilirubin_umol_l=30,pld_bilirubin_band='20_50',anc_x10e9_l=1.6,platelets_x10e9_l=180),'review','The hepatic75% row refers to original dose and must not multiply an already reduced prescription.','L124–L127',match='original')
 add('00205',f'Grade2at two-week review is not the mandatory grade3stop row, {ctx}',dict(**base,ppe_grade=2,stomatitis_grade=0,prior_grade3_4_skin_or_stomatitis=True,toxicity_delay_weeks=2,current_pld_mg_m2=37.5),'review','Current grade2PPE at two weeks calls for a25% reduction review; prior severe history alone is not the current grade3/4 discontinuation row.','L148–L161',forbid_action=['discontinue','permanently_discontinue'])
 add('00205',f'Baseline ECG missing despite completed LVEF investigation, {ctx}',dict(indication_context=ctx,assessment_stage='baseline',baseline_ecg_completed=False,baseline_lvef_completed=True,lvef_percent=65,current_pld_mg_m2=50,correct_pegylated_formulation=True),'review','Baseline ECG and LVEF are separate listed investigations; completing one does not establish the other.','L80–L84',match='ECG')

# PLD20 KS: retain its own indication, count table, interval option and chronology.
for stage in ['baseline','ongoing']:
 base=dict(assessment_stage=stage,administration_source_reconciled=True,correct_pegylated_formulation=True)
 add('00462',f'LowCD4without qualifying disease extent, {stage}',dict(**base,cd4_cells_mm3=100,extensive_mucocutaneous_or_visceral_ks=False,ecog=1,current_pld_mg_m2=20),'review','The indication requires both CD4<200 and extensive mucocutaneous/visceral disease; good performance status cannot replace extent.','L23–L26; L50–L52',match='CD4|Kaposi|extensive|indicat')
 add('00462',f'CD4exactly200with extensive disease, {stage}',dict(**base,cd4_cells_mm3=200,extensive_mucocutaneous_or_visceral_ks=True,current_pld_mg_m2=20,anc_x10e9_l=1.2,platelets_x10e9_l=180),'review','The printed CD4 indication is strictly<200, independently of adequate treatment-day counts.','L23–L26',match='CD4|Kaposi|indicat')
 add('00462',f'KS intermediate counts plus hepatic percentage at prior reduced dose, {stage}',dict(**base,anc_x10e9_l=.8,platelets_x10e9_l=80,bilirubin_umol_l=30,current_pld_mg_m2=10,original_pld_mg_m2=20,prior_count_related_dose_reduction=True),'review','The KS50% count row and hepatic75%-of-original advice cannot be multiplied into a new prescription or use the PLD50 count table.','L95–L97; L113–L116',match='original|previous|prescription')
 add('00462',f'Current severe platelet deficit overrides intermediate ANC and hepatic review, {stage}',dict(**base,anc_x10e9_l=.8,platelets_x10e9_l=45,bilirubin_umol_l=30,current_pld_mg_m2=10,prior_count_related_dose_reduction=True,prior_infusion_reaction=True),'hold','Current platelets<50 require delay even when ANC would enter the50% row and other domains provide future reduction/reinfusion instructions.','L95–L97; L113–L116')
 add('00462',f'Grade2mucositis at two-week review with recovered skin, {stage}',dict(**base,mucositis_grade=2,ppe_grade=0,toxicity_delay_weeks=2,current_pld_mg_m2=15,original_pld_mg_m2=20),'review','Current grade2 stomatitis at two weeks has a reduction versus clinician-discontinuation choice; no automatic new numeric dose or mandatory grade3stop can be invented.','L138–L151',forbid_action=['permanently_discontinue'])
 add('00462',f'Current infusion reaction despite reconciled administration source and grade0, {stage}',dict(**base,current_infusion_reaction=True,infusion_reaction_grade=0,prior_infusion_reaction=False,current_pld_mg_m2=20,anc_x10e9_l=1.2,platelets_x10e9_l=180),'hold','Administration-source reconciliation does not clear a reaction happening now or make a default grade0 reliable.','L45–L48; L189–L193',match='infusion|reaction')
 add('00462',f'Cardiac caution survives normalEFand low cumulative exposure, {stage}',dict(**base,preexisting_cardiomyopathy_or_chf=True,lvef_percent=60,symptomatic_cardiac_dysfunction=False,cumulative_anthracycline_mg_m2=100,current_pld_mg_m2=20),'review','Current NCCP moved pre-existing cardiomyopathy from exclusion to caution; neither silence nor a fabricated absolute contraindication is appropriate.','L67–L68; L227–L229',match='cardiac|cardiomyopathy|heart',forbid_action=['contraindicated'])
 add('00462',f'MildPPEafter previous severe toxicity at planned next cycle, {stage}',dict(**base,ppe_grade=1,stomatitis_grade=0,prior_grade3_4_skin_or_stomatitis=True,toxicity_delay_weeks=0,current_pld_mg_m2=15,anc_x10e9_l=1.2,platelets_x10e9_l=180),'hold','Previous severe skin/mouth toxicity requires a weekly delay despite current grade1 and recovered counts.','L127–L137')
 add('00462',f'Fourteen-day option with five-cycle maximum not yet reached, {stage}',dict(**base,selected_cycle_interval_days=14,completed_cycles=2,cd4_cells_mm3=100,extensive_mucocutaneous_or_visceral_ks=True,current_pld_mg_m2=20),'review','The14-day option needs a separate prescription/calendar decision; it is permitted by the source and does not itself imply permanent cessation.','L31–L33',match='14',forbid_action=['discontinue','permanently_discontinue'])
 add('00462',f'Final scheduled cycle context does not override severe bilirubin rise, {stage}',dict(**base,completed_cycles=5,selected_cycle_interval_days=21,current_pld_mg_m2=20,bilirubin_umol_l=87,mucositis_grade=0,ppe_grade=0),'hold','Being within the six-cycle course does not remove bilirubin>86 not-recommended guidance.','L31–L33; L113–L116',match='bilirubin|hepatic')

# Vinblastine/MTX: independent components, total delay and day/cycle chronology.
for phase in ['baseline','on_treatment','restart']:
 base=dict(assessment_phase=phase)
 add('00554',f'Large third-space collection despite normal renal result and reducedMTX, {phase}',dict(**base,large_third_space_fluid=True,crcl_ml_min=80,actual_mtx_mg_m2=15,anc=1.2,platelets=150,mucositis_grade=0),'hold','Large fluid collections are an exclusion because MTX may accumulate; a normal CrCl and already reduced prescription do not remove that concern.','L43–L49; L169–L170',component_hold=['methotrexate'],match='fluid|ascites|third')
 add('00554',f'Grade2mucositis with grade3neuropathy and normal renal function, {phase}',dict(**base,mucositis_grade=2,neuropathy_grade=3,crcl_ml_min=80,actual_mtx_mg_m2=30,actual_vinblastine_mg_m2=6),'hold','Mucositis grade2 omits MTX; peripheral neuropathy>2 has a separate consultant VBL reduction decision, not a blanket stop of both drugs.','L129–L138',component_hold=['methotrexate'],component_review=['vinblastine'])
 add('00554',f'Numeric14-day count delay contradicts false past-delay flag at reduced baseline, {phase}',dict(**base,delay_days=14,previous_count_delay=False,baseline_vinblastine_mg_m2=4.5,actual_vinblastine_mg_m2=3,anc=1.2,platelets=150,mucositis_grade=0,crcl_ml_min=80),'review','The numeric delay is explicitly total delay due to count toxicity;≥14days invokes25% of baseline VBL, not25% of current3mg/m², despite a contradictory boolean.','L82–L85',component_review=['vinblastine'],match='baseline')
 add('00554',f'Day22rest context despite favourable counts and full prescribed doses, {phase}',dict(**base,treatment_day=22,cycle_number=4,anc=1.2,platelets=150,actual_vinblastine_mg_m2=6,actual_mtx_mg_m2=30),'review','The regimen supplies treatment on Days1,8,15; Day22 is not an extra routine treatment simply because counts are satisfactory.','L26–L36',match='22|rest|schedule')
 add('00554',f'Cycle13Day15requires course review despite lower actual doses, {phase}',dict(**base,treatment_day=15,cycle_number=13,actual_vinblastine_mg_m2=3,actual_mtx_mg_m2=15,anc=1.2,platelets=150),'review','The source course is12cycles; lower doses or an allowed day within a cycle do not establish an automatic13th cycle.','L26–L30',match='12|cycle|course')
 add('00554',f'Concurrent hepaticVBLand mucositisMTXreview with distinct dose bases, {phase}',dict(**base,bilirubin_umol_l=60,bilirubin_analyte='total',mucositis_grade=1,neuropathy_grade=0,actual_vinblastine_mg_m2=3,baseline_vinblastine_mg_m2=6,actual_mtx_mg_m2=15,crcl_ml_min=80),'review','NCCP bilirubin>51 informs original-dose VBL review; grade1mucositis informs MTX reduction separately. Neither percentage may silently propagate to both agents or multiply current doses.','L89–L106; L131–L135',component_review=['vinblastine','methotrexate'])
add('00554','Grade2neuropathy does not inherit MTXgrade1mucositis reduction',dict(assessment_phase='on_treatment',neuropathy_grade=2,mucositis_grade=1,crcl_ml_min=80,actual_vinblastine_mg_m2=6,actual_mtx_mg_m2=30),'review','Source VBL neuropathy reduction guidance starts at grade>2; a separate MTX reduction must not generate VBL withholding.','L131–L135',component_review=['methotrexate'],component_not_hold=['vinblastine'])
add('00554','Missing baseline chestXray despite good counts and ordinary starting doses',dict(assessment_phase='baseline',baseline_chest_xray_done=False,treatment_day=1,cycle_number=1,anc=1.2,platelets=150,actual_mtx_mg_m2=30,actual_vinblastine_mg_m2=6),'review','The baseline chestXray is a separate source-listed investigation; normal counts and dose entries do not establish its completion.','L64–L67',match='chest|X.ray')

assert len(cases)==100
assert all(sum(c['code']==code for c in cases)==20 for code in urls)
Path(__file__).with_name('cases.json').write_text(json.dumps({'design':'Fresh source-first mixed-risk and chronology checks; no author assertions or rule IDs imported.','clinical_approval':False,'cases':cases},indent=2)+'\n')
print('Exactly five suites;100 unique input scenarios,20per regimen')
